import json,subprocess,sys,tempfile
snap=tempfile.NamedTemporaryFile("w",suffix=".json",delete=False)
subprocess.run([sys.executable,"_tools/kbmon.py","--json","--panel","kb"],stdout=snap,stderr=subprocess.DEVNULL); snap.close()
def k(*a): return subprocess.run([sys.executable,"_tools/kbmon.py","--from-snapshot",snap.name,*a],capture_output=True,text=True,timeout=60)
for args in (("--once",),("--count","1","--interval","1")):
    p=k(*args)
    if p.returncode not in (0,1) or "\x1b[" in p.stdout or "kbmon" not in p.stdout: print("piped %s changed: exit %s %r"%(args,p.returncode,p.stdout[:120])); sys.exit(1)
p=k("--json")
try: json.loads(p.stdout)
except ValueError: print("--json is no JSON: %r"%p.stdout[:120]); sys.exit(1)
